INSERT INTO "bills" VALUES(10,'1962','Komisyjny projekt ustawy o zmianie ustawy - Prawo o adwokaturze','2026-09-04T12:52:14','2026-09-04',1,'skipped_prefilter','[]','{"term":10,"number":"1962","title":"Komisyjny projekt ustawy o zmianie ustawy - Prawo o adwokaturze","description":"projekt dotyczy zmian w zakresie finansowania działalności samorządu adwokackiego i gospodarki finansowej jego organów, zadań samorządu i kompetencji jego organów, obowiązków adwokatów i aplikantów adwokackich dotyczących świadczenia pomocy prawnej, obowiązków adwokatów związanych z członkostwem w samorządzie i ich odpowiedzialności dyscyplinarnej","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2025-10-17","document_date":"2025-10-16","change_date":"2026-09-04T12:52:14","closure_date":"2026-09-04","passed":true,"urgency_status":"NORMAL","eu_related":false,"rcl_num":null,"rcl_link":null,"prints_considered_jointly":[]}',NULL,NULL,NULL,0,NULL,'2026-09-07T13:52:14+00:00','2026-09-07T13:52:14+00:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
