INSERT INTO "bills" VALUES(10,'2580','Rządowy projekt ustawy o osobistych kontach inwestycyjnych','2026-08-27T11:16:56','2026-07-03',1,'skipped_prefilter','[]','{"term":10,"number":"2580","title":"Rządowy projekt ustawy o osobistych kontach inwestycyjnych","description":"projekt dotyczy wprowadzenia nowych, dobrowolnych i bezpłatnych narzędzi do oszczędzania oraz inwestowania ? Osobiste Konto Inwestycyjne (OKI). Rozwiązanie umożliwi inwestowanie w akcje, obligacje oraz inne instrumenty finansowe z pełnym zwolnieniem od podatku dochodowego do 100 tys. zł. Dla aktywów oszczędnościowych, takich jak lokaty czy obligacje oszczędnościowe, zwolnienie wyniesie do 25 tys. zł. Projekt stanowi realizację priorytetów rządu. Nowe przepisy zaczną obowiązywać od 2027 roku.","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-05-08","document_date":"2026-05-08","change_date":"2026-08-27T11:16:56","closure_date":"2026-07-03","passed":true,"urgency_status":"NORMAL","eu_related":false,"rcl_num":null,"rcl_link":null,"prints_considered_jointly":[]}',NULL,NULL,NULL,0,NULL,'2026-09-07T13:52:14+00:00','2026-09-07T13:52:14+00:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
