INSERT INTO "bills" VALUES(10,'2677','Rządowy projekt ustawy o zmianie ustawy o podatku od towarów i usług oraz ustawy o zasadach ewidencji i identyfikacji podatników i płatników','2026-09-04T12:51:49','2026-09-04',1,'skipped_prefilter','[]','{"term":10,"number":"2677","title":"Rządowy projekt ustawy o zmianie ustawy o podatku od towarów i usług oraz ustawy o zasadach ewidencji i identyfikacji podatników i płatników","description":"projekt dotyczy wprowadzenia rozwiązań ograniczających część obowiązków administracyjnych dla przedsiębiorców, które ułatwią prowadzenie działalności m.in. poprzez likwidację wybranych obowiązków administracyjnych, tj.: (1) zniesienie obowiązku składania oddzielnej informacji o spisie z natury; (2) rezygnację z obowiązku wykazywania w JPK_VAT podstawy opodatkowania przy zakupach od podatników spoza terytorium Polski, towarów i usług objętych zwolnieniem z podatku; (3) likwidację obowiązku zapłaty VAT w ciągu 14 dni przy zakupie środka transportu z innego państwa UE; (4) ograniczenie naliczania odsetek od VAT przy imporcie w sytuacjach, gdy opóźnienie płatności jest niezależne od podatnika","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-06-09","document_date":"2026-06-09","change_date":"2026-09-04T12:51:49","closure_date":"2026-09-04","passed":true,"urgency_status":"NORMAL","eu_related":false,"rcl_num":null,"rcl_link":null,"prints_considered_jointly":[]}',NULL,NULL,NULL,0,NULL,'2026-09-07T13:52:14+00:00','2026-09-07T13:52:14+00:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "bills" VALUES(10,'2693','Rządowy projekt ustawy o zmianie ustawy o świadczeniu usług drogą elektroniczną oraz niektórych innych ustaw','2026-09-03T10:13:34',NULL,0,'skipped_prefilter','[]','{"term":10,"number":"2693","title":"Rządowy projekt ustawy o zmianie ustawy o świadczeniu usług drogą elektroniczną oraz niektórych innych ustaw","description":"projekt dotyczy zapewnienia skuteczniejszych narzędzi do reagowania na nielegalne treści","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-06-09","document_date":"2026-06-09","change_date":"2026-09-03T10:13:34","closure_date":null,"passed":false,"urgency_status":"NORMAL","eu_related":false,"rcl_num":null,"rcl_link":null,"prints_considered_jointly":[]}',NULL,NULL,NULL,0,NULL,'2026-09-07T13:52:14+00:00','2026-09-07T13:52:14+00:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "bills" VALUES(10,'2694','Rządowy projekt ustawy o zmianie ustawy o świadczeniu usług drogą elektroniczną oraz niektórych innych ustaw','2026-09-04T12:53:42','2026-09-04',1,'skipped_prefilter','[]','{"term":10,"number":"2694","title":"Rządowy projekt ustawy o zmianie ustawy o świadczeniu usług drogą elektroniczną oraz niektórych innych ustaw","description":"projekt dotyczy ustanowienia Prezesa Urzędu Komunikacji Elektronicznej głównym organem nadzorującym stosowanie nowych przepisów i pełniącym funkcję koordynatora ds. usług cyfrowych; wprowadzenia nowych mechanizmów rozpatrywania sporów, zgłoszeń nielegalnych treści oraz dostępu do danych dużych platform internetowych, w celach naukowych dotyczących m.in. dezinformacji czy bezpieczeństwa w sieci","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-06-09","document_date":"2026-06-09","change_date":"2026-09-04T12:53:42","closure_date":"2026-09-04","passed":true,"urgency_status":"NORMAL","eu_related":false,"rcl_num":null,"rcl_link":null,"prints_considered_jointly":[]}',NULL,NULL,NULL,0,NULL,'2026-09-07T13:52:14+00:00','2026-09-07T13:52:14+00:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "bills" VALUES(10,'2698','Rządowy projekt ustawy o zmianie ustawy o opiece nad dziećmi w wieku do lat 3 oraz niektórych innych ustaw','2026-08-27T11:21:36','2026-07-31',1,'skipped_prefilter','[]','{"term":10,"number":"2698","title":"Rządowy projekt ustawy o zmianie ustawy o opiece nad dziećmi w wieku do lat 3 oraz niektórych innych ustaw","description":"projekt dotyczy wprowadzenia nowej formy opieki - punkt opieki dziennej; wprowadzenia nowych uprawnień dla osób pracujących z najmłodszymi dziećmi (w tym m.in.: płatny czas na podnoszenie kwalifikacji zawodowych; 33-procentowa ulga na przejazdy publicznym transportem zbiorowym); nowe wymagania dotyczące plac zabaw przy żłobkach; propozycji ustanowienia 4 kwietnia Dniem Opiekuna Małego Dziecka","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-06-09","document_date":"2026-06-09","change_date":"2026-08-27T11:21:36","closure_date":"2026-07-31","passed":true,"urgency_status":"NORMAL","eu_related":false,"rcl_num":null,"rcl_link":null,"prints_considered_jointly":[]}',NULL,NULL,NULL,0,NULL,'2026-09-07T13:52:14+00:00','2026-09-07T13:52:14+00:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "bills" VALUES(10,'2699','Rządowy projekt ustawy o zmianie ustawy o nabywaniu nieruchomości przez cudzoziemców oraz ustawy - Prawo o notariacie','2026-08-27T09:18:01+00:00','2026-07-17',1,'analyzed','["cudzoziemcy", "nieruchomosci_cudzoziemcy"]','{"term":10,"number":"2699","title":"Rządowy projekt ustawy o zmianie ustawy o nabywaniu nieruchomości przez cudzoziemców oraz ustawy - Prawo o notariacie","description":"projekt dotyczy usprawnienia kontroli nabywania przez cudzoziemców nieruchomości w Polsce. Notariusze będą przesyłać dokumenty do Ministerstwa Spraw Wewnętrznych i Administracji wyłącznie w formie elektronicznej. Dzięki temu ich obieg stanie się szybszy, bezpieczniejszy i bardziej przejrzysty. Zmiany wpisują się w proces cyfryzacji administracji publicznej i poprawiają nadzór nad zakupem nieruchomości przez cudzoziemców","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-06-09","document_date":"2026-06-09","change_date":"2026-08-27T09:18:01Z","closure_date":"2026-07-17","passed":true,"urgency_status":"NORMAL","eu_related":false,"rcl_num":"RM-0610-81-26","rcl_link":"https://legislacja.rcl.gov.pl/getIdFromLegislacja?number=RM-0610-81-26","prints_considered_jointly":[],"applicant":null,"eli":"DU/2026/1099","display_address":"Dz.U. 2026 poz. 1099","isap_url":"https://isap.sejm.gov.pl/isap.nsf/DocDetails.xsp?id=WDU20260001099","stages":[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-06-09","print_number":"2699","sitting_num":null,"decision":null,"committee_code":null,"report_file":null,"text_after3":null,"position":null,"proposal":null,"sub_committee":false,"voting":null,"committee_name":null,"children":[]},{"stage_name":"Skierowano do I czytania w komisjach","stage_type":"ReadingReferral","date":"2026-06-17","print_number":null,"sitting_num":null,"decision":null,"committee_code":null,"report_file":null,"text_after3":null,"position":null,"proposal":null,"sub_committee":false,"voting":nu