INSERT INTO "bills" VALUES(10,'2810','Rządowy projekt ustawy o ratyfikacji Umowy między Rzecząpospolitą Polską a Japonią o zabezpieczeniu społecznym, podpisanej w Tokio dnia 15 kwietnia 2026 r.','2026-09-03T16:18:19',NULL,0,'skipped_prefilter','[]','{"term":10,"number":"2810","title":"Rządowy projekt ustawy o ratyfikacji Umowy między Rzecząpospolitą Polską a Japonią o zabezpieczeniu społecznym, podpisanej w Tokio dnia 15 kwietnia 2026 r.","description":"projekt dotyczy m.in. możliwości sumowania polskich oraz japońskich okresów ubezpieczenia, w celu przyznania prawa do świadczeń oraz możliwości dokonywania wypłaty\npolskich świadczeń osobom uprawnionym mającym miejsce zamieszkania na terytorium Japonii","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-07-13","document_date":"2026-07-13","change_date":"2026-09-03T16:18:19","closure_date":null,"passed":false,"urgency_status":"NORMAL","eu_related":false,"rcl_num":null,"rcl_link":null,"prints_considered_jointly":[]}',NULL,NULL,NULL,0,NULL,'2026-09-07T13:52:14+00:00','2026-09-07T13:52:14+00:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "bills" VALUES(10,'2821','Rządowy projekt ustawy o zmianie ustawy o odnawialnych źródłach energii oraz niektórych innych ustaw','2026-09-04T12:49:12','2026-09-04',1,'skipped_prefilter','[]','{"term":10,"number":"2821","title":"Rządowy projekt ustawy o zmianie ustawy o odnawialnych źródłach energii oraz niektórych innych ustaw","description":"projekt dotyczy m.in.: powstania nowego systemu wsparcia dla instalacji produkujących biometan o mocy większej niż 1 MW, złagodzenia zasad udziału części instalacji wykorzystujących biogaz i biomasę w systemie aukcyjnym OZE, ułatwienia zasad budowy tzw. gazociągów bezpośrednich, czyli połączeń, które umożliwiają dostarczanie biogazu lub biometanu bezpośrednio od producenta do odbiorcy, z pominięciem ogólnej sieci gazowej, doprecyzowania zasad działania spółdzielni energetycznych, czyli grup mieszkańców, przedsiębiorców lub samorządów, które wspólnie produkują i wykorzystują energię","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-07-15","document_date":"2026-07-15","change_date":"2026-09-04T12:49:12","closure_date":"2026-09-04","passed":true,"urgency_status":"NORMAL","eu_related":false,"rcl_num":null,"rcl_link":null,"prints_considered_jointly":[]}',NULL,NULL,NULL,0,NULL,'2026-09-07T13:52:14+00:00','2026-09-07T13:52:14+00:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
