INSERT INTO "bills" VALUES(10,'3003','Rządowy projekt ustawy o środkach ograniczających','2026-09-04T11:16:17',NULL,0,'skipped_prefilter','[]','{"term":10,"number":"3003","title":"Rządowy projekt ustawy o środkach ograniczających","description":"projekt dotyczy określenia kompetencji organów oraz zasad ich współpracy; utworzenia przejrzystego systemu krajowych środków ograniczających, w tym wprowadzenia nowych przesłanek pozwalających na wpis na listę sankcyjną - za ingerencję i manipulację informacjami wymierzoną w bezpieczeństwo narodowe. Projekt określa też kary za naruszanie i obchodzenie sankcji.","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-08-06","document_date":"2026-08-06","change_date":"2026-09-04T11:16:17","closure_date":null,"passed":false,"urgency_status":"NORMAL","eu_related":false,"rcl_num":null,"rcl_link":null,"prints_considered_jointly":[]}',NULL,NULL,NULL,0,NULL,'2026-09-07T13:52:14+00:00','2026-09-07T13:52:14+00:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
