INSERT INTO "bills" VALUES(10,'3033','Poselski projekt ustawy o zmianie ustawy o transporcie kolejowym','2026-09-02T08:41:16',NULL,0,'skipped_prefilter','[]','{"term":10,"number":"3033","title":"Poselski projekt ustawy o zmianie ustawy o transporcie kolejowym","description":"projekt dotyczy wprowadzenia mechanizmów ochrony polskiego oraz unijnego rynku kolejowych przewozów rzeczy przed sytuacjami, w których przedsiębiorcy kontrolowani przez podmioty pochodzące z państw trzecich uzyskują dostęp do rynku Rzeczypospolitej Polskiej, podczas gdy przewoźnicy kolejowi z Polski oraz innych państw członkowskich Unii Europejskiej nie posiadają rzeczywistego, porównywalnego i niedyskryminacyjnego dostępu do rynku kolejowych przewozów rzeczy w tych państwach","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-06-11","document_date":"2026-06-11","change_date":"2026-09-02T08:41:16","closure_date":null,"passed":false,"urgency_status":"NORMAL","eu_related":false,"rcl_num":null,"rcl_link":null,"prints_considered_jointly":[]}',NULL,NULL,NULL,0,NULL,'2026-09-07T13:52:14+00:00','2026-09-07T13:52:14+00:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
