INSERT INTO "bills" VALUES(10,'3035','Poselski projekt ustawy o zmianie ustawy o Agencji Bezpieczeństwa Wewnętrznego oraz Agencji Wywiadu, ustawy o Centralnym Biurze Antykorupcyjnym, ustawy o Służbie Kontrwywiadu Wojskowego oraz niektórych innych ustaw','2026-09-07T06:12:58+00:00',NULL,0,'skipped_prefilter','[]','{"term":10,"number":"3035","title":"Poselski projekt ustawy o zmianie ustawy o Agencji Bezpieczeństwa Wewnętrznego oraz Agencji Wywiadu, ustawy o Centralnym Biurze Antykorupcyjnym, ustawy o Służbie Kontrwywiadu Wojskowego oraz niektórych innych ustaw","description":"projekt dotyczy wyłączenia obiektów budowlanych usytuowanych na terenach zamkniętych ustalonych decyzją szefów służb specjalnych od obowiązku zamieszczania informacji dotyczących inwestycji na stronach Biuletynu Informacji Publicznej właściwego organu administracji architektoniczno-budowlanej, nie będzie wymagana decyzja o pozwoleniu na rozbiórkę oraz zgłoszenie rozbiórki budynków i budowli zlokalizowanych na terenach zamkniętych ustalonych również decyzją szefów służb specjalnych oraz wyłączenia obowiązku zgłoszenia zmiany sposobu użytkowania obiektu budowlanego lub jego części w zakresie obiektów budowlanych zlokalizowanych na tych terenach; Poszerza się ustawowy katalog zadań ABW, AW, CBA, SKW i SWW o zapewnienie ochrony Szefom tych służb (oraz w uzasadnionych przypadkach wskazanemu funkcjonariuszowi lub pracownikowi)","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-07-30","document_date":"2026-07-30","change_date":"2026-09-07T06:12:58Z","closure_date":null,"passed":false,"urgency_status":"NORMAL","eu_related":false,"rcl_num":null,"rcl_link":null,"prints_considered_jointly":[],"applicant":null,"eli":null,"display_address":null,"isap_url":null}',NULL,NULL,NULL,0,NULL,'2026-09-07T13:52:14+00:00','2026-09-08T09:26:00+00:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "bills" VALUES(10,'3036','Poselski projekt ustawy o zmianie ustawy o elektromobilności i paliwach alternatywnych','2026-09-07T06:15:16+00:00',NULL,0,'skipped_prefilter','[]','{"term":10,"number":"3036","title":"Poselski projekt ustawy o zmianie ustawy o elektromobilności i paliwach alternatywnych","description":"projekt dotyczy rozszerzenia katalogu dopuszczalnych sposobów wykorzystania dochodów z opłat o finansowanie zadań własnych gminy w zakresie lokalnego transportu zbiorowego, o których mowa w art. 7 ust. 1 pkt 4 ustawy o samorządzie gminnym. Projektowana zmiana zwiększy swobodę gmin w wykorzystywaniu tych środków, przy zachowaniu ich przeznaczenia na cele związane z transportem zbiorowym.","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-07-22","document_date":"2026-07-22","change_date":"2026-09-07T06:15:16Z","closure_date":null,"passed":false,"urgency_status":"NORMAL","eu_related":false,"rcl_num":null,"rcl_link":null,"prints_considered_jointly":[],"applicant":null,"eli":null,"display_address":null,"isap_url":null}',NULL,NULL,NULL,0,NULL,'2026-09-07T13:52:14+00:00','2026-09-08T09:26:00+00:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
