INSERT INTO "bills" VALUES(10,'2822','Rządowy projekt ustawy o zmianie niektórych ustaw w celu wsparcia zrównoważonego lotnictwa','2026-09-08T09:18:50+00:00','2026-07-31',1,'skipped_text_prefilter','[]','{"term":10,"number":"2822","title":"Rządowy projekt ustawy o zmianie niektórych ustaw w celu wsparcia zrównoważonego lotnictwa","description":"projekt dotyczy dostosowania polskiego prawa do przepisów Unii Europejskiej dotyczących ograniczania emisji gazów cieplarnianych w lotnictwie. Nowe rozwiązania wyrównają szanse mniejszych i średnich przewoźników lotniczych, w tym polskich, na europejskim rynku. Zmiany zlikwidują dotychczasowe preferencje dla największych linii lotniczych i będą zachęcać przewoźników do korzystania z bardziej ekologicznych paliw","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-07-16","document_date":"2026-07-15","change_date":"2026-09-08T09:18:50Z","closure_date":"2026-07-31","passed":true,"urgency_status":"NORMAL","eu_related":true,"rcl_num":null,"rcl_link":null,"prints_considered_jointly":[],"applicant":null,"eli":"DU/2026/1157","display_address":"Dz.U. 2026 poz. 1157","isap_url":"https://isap.sejm.gov.pl/isap.nsf/DocDetails.xsp?id=WDU20260001157"}',NULL,NULL,NULL,0,NULL,'2026-09-08T09:26:00+00:00','2026-09-09T14:39:55+00:00','{"term":10,"number":"RPW/24579/2026","title":"Rządowy projekt ustawy o zmianie niektórych ustaw w celu wsparcia zrównoważonego lotnictwa","description":"dostosowania polskiego prawa do przepisów Unii Europejskiej dotyczących ograniczania emisji gazów cieplarnianych w lotnictwie. Nowe rozwiązania wyrównają szanse mniejszych i średnich przewoźników lotniczych, w tym polskich, na europejskim rynku. Zmiany zlikwidują dotychczasowe preferencje dla największych linii lotniczych i będą zachęcać przewoźników do korzystania z bardziej ekologicznych paliw","applicant":"government","status":"ACTIVE","submission_type":"BILL","date_of_receipt":"2026-07-15","print_number":"2822","eu_related":t