INSERT INTO "bills" VALUES(10,'RCL/12401805','Projekt ustawy o zapewnieniu gospodarce krajowej dostępu do surowców, w tym surowców krytycznych','2026-09-08T00:00:00+00:00',NULL,NULL,'skipped_prefilter','[]','{"term":10,"number":"RCL/12401805","title":"Projekt ustawy o zapewnieniu gospodarce krajowej dostępu do surowców, w tym surowców krytycznych","description":"GEOLOGICZNE PRAWO; gospodarka surowcami energetycznymi. Numer i tytuł aktu prawnego Unii Europejskiej: rozporządzenie Parlamentu Europejskiego i Rady (UE) 2024/1252 z dnia 11 kwietnia 2024 r. w sprawie ustanowienia ram na potrzeby zapewnienia bezpiecznych i zrównoważonych dostaw surowców krytycznych oraz zmiany rozporządzeń (UE) nr 168/2013, (UE) 2018/858, (UE) 2018/1724 i (UE) 2019/1020 (Dz. Urz. UE L 1252 z 3.5.2024, str. 1, z późn. zm.)","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2025-09-05","document_date":"2025-09-05","change_date":"2026-09-08T00:00:00Z","closure_date":null,"passed":null,"urgency_status":null,"eu_related":true,"rcl_num":null,"rcl_link":"https://legislacja.rcl.gov.pl/projekt/12401805","prints_considered_jointly":[],"applicant":"government","eli":null,"display_address":null,"isap_url":null}','[{"stage_name": "2. Uzgodnienia", "stage_type": "RclStage", "date": null, "print_number": null, "sitting_num": null, "decision": null, "committee_code": null, "report_file": null, "text_after3": null, "position": null, "proposal": null, "sub_committee": false, "voting": null, "committee_name": null, "children": []}, {"stage_name": "3. Konsultacje publiczne", "stage_type": "RclStage", "date": null, "print_number": null, "sitting_num": null, "decision": null, "committee_code": null, "report_file": null, "text_after3": null, "position": null, "proposal": null, "sub_committee": false, "voting": null, "committee_name": null, "children": []}, {"stage_name": "4. Opiniowanie", "stage_type": "RclStage", "date": null, "print_number": null, "sitting_num": null, "decision"